      "24": { "level": "Tube forming tooling supports 6 frame sizes with standard dies. No unique tooling per size variant required." },
      "25": { "level": "Round aluminum tube provides near-zero intrinsic vibration damping. RMS acceleration reduction = 0% — this is the baseline definition." },
